const users = $input.item.json.users;
const executives = users
  .filter(u => u.role === "executive")
  .map(u => u.email);

const { siren, id } = $('Keep w/ SIREN').item.json;

return { json: { executives, siren, id } };

// Extract source datasets and identifier from the input
const { identifier, accounts_month, accounts_prior, accounts_ytd } = $('Merge All Data').item.json;

// Transforms a list of raw accounts into a structured format
const transformBalances = (accountList) => {
  if (!accountList || !Array.isArray(accountList)) {
    return [];
  }

  return accountList.map(account => ({
    account: String(account.formatted_number || account.number || ""),
    balance: (Number(account.debits) || 0) - (Number(account.credits) || 0)
  }));
};

// Consolidate transformed data into the final output structure
return {
  identifier,
  entries_month: transformBalances(accounts_month),
  entries_prior: transformBalances(accounts_prior),
  entries_ytd: transformBalances(accounts_ytd),
};

const map = Object.fromEntries($("Is Uncomplete?").all().map(i => [i.json.id, i.json]));

return $input.all().filter(i => {
  const match = map[i.json.identifier];
  return match && Object.assign(i.json, match);
});
